78	@RestController
79	@CrossOrigin(exposedHeaders = "errors, content-type")
80	@RequestMapping("/api")
81	public class OwnerRestControllerV1 implements OwnersApi {
82	
83	    private final ClinicService clinicService;
84	
85	    private final OwnerMapper ownerMapper;
86	
87	    private final PetMapper petMapper;
88	
89	    private final VisitMapper visitMapper;
90	
91	    private final OwnerFieldsValidator ownerFieldsValidator;
92	
93	    private final PostcodeValidator postcodeValidator;
94	
95	    private final RegistrationDateValidator registrationDateValidator;
96	
97	    private final HouseholdDuplicateValidator householdDuplicateValidator;
98	
99	    private final IdentityDuplicateValidator identityDuplicateValidator;
100	
101	    private final PossibleDuplicateDetector possibleDuplicateDetector;
102	
103	    private final HouseholdIdGenerator householdIdGenerator;
104	
105	    private final TelephoneNormalizer telephoneNormalizer;
106	
107	    private final EmailNormalizer emailNormalizer;
108	
109	    private final DisposableEmailDomainValidator disposableEmailDomainValidator;
110	
111	    private final AddressResolver addressResolver;
112	
113	    private final CustomerCodeGenerator customerCodeGenerator;
114	
115	    private final NamesakeCounter namesakeCounter;
116	
117	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
118	
119	    private final OwnerAuditLogger ownerAuditLogger;
120	
121	    private final OwnerCreationIdempotencyStore idempotencyStore;
122	
123	    private final HttpServletRequest request;
124	
125	    public OwnerRestControllerV1(ClinicService clinicService,
126	                                 OwnerMapper ownerMapper,
127	                                 PetMapper petMapper,
128	                                 VisitMapper visitMapper,
129	                                 OwnerFieldsValidator ownerFieldsValidator,
130	                                 PostcodeValidator postcodeValidator,
131	                                 RegistrationDateValidator registrationDateValidator,
132	                                 HouseholdDuplicateValidator householdDuplicateValidator,
133	                                 IdentityDuplicateValidator identityDuplicateValidator,
134	                                 PossibleDuplicateDetector possibleDuplicateDetector,
135	                                 HouseholdIdGenerator householdIdGenerator,
136	                                 TelephoneNormalizer telephoneNormalizer,
137	                                 EmailNormalizer emailNormalizer,
138	                                 DisposableEmailDomainValidator disposableEmailDomainValidator,
139	                                 AddressResolver addressResolver,
140	                                 CustomerCodeGenerator customerCodeGenerator,
141	                                 NamesakeCounter namesakeCounter,
142	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
143	                                 OwnerAuditLogger ownerAuditLogger,
144	                                 OwnerCreationIdempotencyStore idempotencyStore,
145	                                 HttpServletRequest request) {
146	        this.clinicService = clinicService;
147	        this.ownerMapper = ownerMapper;
148	        this.petMapper = petMapper;
149	        this.visitMapper = visitMapper;
150	        this.ownerFieldsValidator = ownerFieldsValidator;
151	        this.postcodeValidator = postcodeValidator;
152	        this.registrationDateValidator = registrationDateValidator;
153	        this.householdDuplicateValidator = householdDuplicateValidator;
154	        this.identityDuplicateValidator = identityDuplicateValidator;
155	        this.possibleDuplicateDetector = possibleDuplicateDetector;
156	        this.householdIdGenerator = householdIdGenerator;
157	        this.telephoneNormalizer = telephoneNormalizer;
158	        this.emailNormalizer = emailNormalizer;
159	        this.disposableEmailDomainValidator = disposableEmailDomainValidator;
160	        this.addressResolver = addressResolver;
161	        this.customerCodeGenerator = customerCodeGenerator;
162	        this.namesakeCounter = namesakeCounter;
163	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
164	        this.ownerAuditLogger = ownerAuditLogger;
165	        this.idempotencyStore = idempotencyStore;
166	        this.request = request;
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
172	        Collection<Owner> owners;
173	        if (lastName != null) {
174	            owners = this.clinicService.findOwnerByLastName(lastName);
175	        } else {
176	            owners = this.clinicService.findAllOwners();
177	        }
178	        if (owners.isEmpty()) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
187	        Owner owner = this.clinicService.findOwnerById(ownerId);
188	        if (owner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
197	        String idempotencyKey = idempotencyKey();
198	        ResponseEntity<OwnerDto> replay = replayIfDuplicateKey(idempotencyKey);
199	        if (replay != null) {
200	            return replay;
201	        }
202	        addressResolver.resolve(ownerFieldsDto);
203	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
204	        if (!missingFields.isEmpty()) {
205	            throw new MissingOwnerFieldsException(missingFields);
206	        }
207	        HttpHeaders headers = new HttpHeaders();
208	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
209	        Collection<Owner> sameLastName =
210	            activeOwners(this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName()));
211	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
212	        List<Owner> householdMembers = assignHousehold(owner, sameLastName);
213	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
214	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
215	        disposableEmailDomainValidator.validate(owner.getEmail());
216	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
217	        rejectIfDuplicateIdentity(owner);
218	        applyHouseholdRule(owner, ownerFieldsDto, householdMembers, sameLastName);
219	        registrationDateValidator.validate(owner.getRegistrationDate());
220	        if (owner.getRegistrationDate() == null) {
221	            owner.setRegistrationDate(LocalDate.now());
222	        }
223	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
224	        LocalDate registrationDate = owner.getRegistrationDate();
225	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
226	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
227	            throw new DailyOwnerLimitException(registrationDate);
228	        }
229	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
230	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
231	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
232	            throw new CityOwnerLimitException(owner.getCity());
233	        }
234	        owner.setCustomerCode(assignCustomerCode(owner));
235	        this.clinicService.saveOwner(owner);
236	        if (idempotencyKey != null) {
237	            idempotencyStore.record(idempotencyKey, owner.getId());
238	        }
239	        ownerAuditLogger.ownerCreated(owner);
240	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
241	        headers.setLocation(UriComponentsBuilder.newInstance()
242	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
243	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
244	    }
245	
246	    /**
247	     * Reads the request's {@code Idempotency-Key} header, treating a blank value as absent.
248	     *
249	     * @return the trimmed key, or {@code null} when the request carries no usable key
250	     */
251	    private String idempotencyKey() {
252	        String key = request.getHeader("Idempotency-Key");
253	        return StringUtils.hasText(key) ? key.trim() : null;
254	    }
255	
256	    /**
257	     * Replays the owner originally created for an already-seen idempotency key, so a repeated
258	     * create returns that owner with 200 instead of storing a duplicate. Returns {@code null}
259	     * when there is no key or the key has not been seen, in which case the create proceeds
260	     * normally.
261	     */
262	    private ResponseEntity<OwnerDto> replayIfDuplicateKey(String idempotencyKey) {
263	        if (idempotencyKey == null) {
264	            return null;
265	        }
266	        return idempotencyStore.find(idempotencyKey)
267	            .map(clinicService::findOwnerById)
268	            .map(ownerMapper::toOwnerDto)
269	            .map(ownerDto -> new ResponseEntity<>(ownerDto, HttpStatus.OK))
270	            .orElse(null);
271	    }
272	
273	    /**
274	     * Assigns the household attributes of an owner about to be created, without touching any
275	     * existing owner. The {@code householdId} is derived deterministically from the owner's last
276	     * name and postcode, so every owner in the same household shares it automatically regardless of
277	     * creation order. The new owner's household size after this create is recorded: the existing
278	     * members that share its household (same last name and postcode) plus the owner itself.
279	     *
280	     * @return the existing members of the owner's household (empty when it starts a new household)
281	     */
282	    private List<Owner> assignHousehold(Owner owner, Collection<Owner> sameLastName) {
283	        owner.setHouseholdId(householdIdGenerator.generate(owner));
284	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
285	        owner.setHouseholdSize(members.size() + 1);
286	        return members;
287	    }
288	
289	    /**
290	     * Computes the customer code for an owner about to be created, de-duplicated against the codes
291	     * already assigned to existing owners so that distinct owners always receive distinct codes.
292	     *
293	     * @return the owner's unique customer code
294	     */
295	    private String assignCustomerCode(Owner owner) {
296	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
297	        String baseCode = customerCodeGenerator.generate(
298	            region, owner.getTelephone(), owner.getLastName());
299	        List<String> takenCodes = clinicService.findOwnersByCustomerCodeStartingWith(baseCode)
300	            .stream()
301	            .map(Owner::getCustomerCode)
302	            .toList();
303	        return customerCodeGenerator.deduplicate(baseCode, takenCodes);
304	    }
305	
306	    /**
307	     * Applies the household-membership rule once the owner has cleared hard duplicate detection.
308	     * When the owner joins an existing household (same last name and postcode) it is rejected as a
309	     * household duplicate, unless the request declared {@code sharesHousehold}: a declared member is
310	     * created and, being knowingly registered, is not treated as a suspected duplicate. When the
311	     * owner starts a new household the ordinary possible-duplicate detection runs.
312	     *
313	     * @throws HouseholdDuplicateException if the owner joins an existing household without opting in
314	     */
315	    private void applyHouseholdRule(Owner owner, OwnerFieldsDto ownerFieldsDto,
316	                                    List<Owner> householdMembers, Collection<Owner> sameLastName) {
317	        if (householdMembers.isEmpty()) {
318	            flagPossibleDuplicate(owner, sameLastName);
319	            return;
320	        }
321	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
322	            throw new HouseholdDuplicateException(owner.getHouseholdId());
323	        }
324	        owner.setPossibleDuplicate(false);
325	        owner.setPossibleDuplicateOf(null);
326	    }
327	
328	    /**
329	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
330	     * owner. A full-key match requires an equal telephone, so only owners with the same
331	     * (already normalized) telephone are compared.
332	     *
333	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
334	     */
335	    private void rejectIfDuplicateIdentity(Owner owner) {
336	        Collection<Owner> sameTelephone =
337	            activeOwners(this.clinicService.findOwnersByTelephone(owner.getTelephone()));
338	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
339	            throw new DuplicateIdentityException(IdentityKey.of(owner));
340	        }
341	    }
342	
343	    /**
344	     * Filters out soft-deleted owners, so the create endpoint's duplicate and identity checks
345	     * consider only owners that are still active. A soft-deleted owner keeps its row but is
346	     * treated as absent for the purpose of detecting duplicates of a newly created owner.
347	     */
348	    private List<Owner> activeOwners(Collection<Owner> owners) {
349	        return owners.stream().filter(candidate -> !candidate.isDeleted()).toList();
350	    }
351	
352	    /**
353	     * Flags the owner as a soft (possible) duplicate when it is not a hard duplicate yet shares an
354	     * existing owner's last name and postcode with a different telephone. The matching owner's id
355	     * is recorded in {@code possibleDuplicateOf}; when nothing matches the owner is stamped as not
356	     * a possible duplicate. Called after {@link #rejectIfDuplicateIdentity(Owner)}, so any candidate
357	     * seen here is guaranteed not to be a hard duplicate.
358	     */
359	    private void flagPossibleDuplicate(Owner owner, Collection<Owner> sameLastName) {
360	        Owner match = possibleDuplicateDetector.findPossibleDuplicate(owner, sameLastName).orElse(null);
361	        owner.setPossibleDuplicate(match != null);
362	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
363	    }
364	
365	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
366	    @Override
367	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
368	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
369	        if (currentOwner == null) {
370	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
371	        }
372	        currentOwner.setAddress(ownerFieldsDto.getAddress());
373	        currentOwner.setCity(ownerFieldsDto.getCity());
374	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
375	        currentOwner.setLastName(ownerFieldsDto.getLastName());
376	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
377	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
378	        this.clinicService.saveOwner(currentOwner);
379	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
380	    }
381	
382	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
383	    @Transactional
384	    @Override
385	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
386	        Owner owner = this.clinicService.findOwnerById(ownerId);
387	        if (owner == null) {
388	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
389	        }
390	        owner.setDeleted(true);
391	        this.clinicService.saveOwner(owner);
392	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
393	    }
394	
395	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
396	    @Override
397	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
398	        Owner owner = this.clinicService.findOwnerById(ownerId);
399	        if (owner == null) {
400	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
401	        }
402	        HttpHeaders headers = new HttpHeaders();
403	        Pet pet = petMapper.toPet(petFieldsDto);
404	        owner.setId(ownerId);
405	        pet.setOwner(owner);
406	        pet.getType().setName(null);
407	        this.clinicService.savePet(pet);
408	        PetDto petDto = petMapper.toPetDto(pet);
409	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
410	            .buildAndExpand(pet.getId()).toUri());
411	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
412	    }
413	
414	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
415	    @Override
416	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
417	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
418	        if (currentOwner != null) {
419	            Pet currentPet = this.clinicService.findPetById(petId);
420	            if (currentPet != null) {
421	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
422	                currentPet.setName(petFieldsDto.getName());
423	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
424	                this.clinicService.savePet(currentPet);
425	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
426	            }
427	        }
428	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
429	    }
430	
431	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
432	    @Override
433	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
434	        HttpHeaders headers = new HttpHeaders();
435	        Visit visit = visitMapper.toVisit(visitFieldsDto);
436	        Pet pet = new Pet();
437	        pet.setId(petId);
438	        visit.setPet(pet);
439	        this.clinicService.saveVisit(visit);
440	        VisitDto visitDto = visitMapper.toVisitDto(visit);
441	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
442	            .buildAndExpand(visit.getId()).toUri());
443	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
444	    }
445	
446	
447	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
448	    @Override
449	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
450	        Owner owner = this.clinicService.findOwnerById(ownerId);
451	        if (owner != null) {
452	            Pet pet = owner.getPet(petId);
453	            if (pet != null) {
454	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
455	            }
456	        }
457	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
458	    }
459	}
